    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> meetings(n, vector<long long>(2));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> meetings[i][j];
        }
    }

    sort(meetings.begin(), meetings.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[1] < y[1]; });
    long long kept = 0, lastEnd = -1;
    for (const vector<long long>& m : meetings) {
        if (m[0] >= lastEnd) {
            kept++;
            lastEnd = m[1];
        }
    }
    cout << n - kept << "\n";

    return 0;
}

